import React from "react";

const SubscriptionDecorations = () => {
  return (
    <div
      className="subscription-decoration"
      data-aos="fade-down"
      data-aos-delay="200"
    >
      <div className="subscription-decoration--1"></div>
      <div className="subscription-decoration--2"></div>
      <div className="subscription-decoration--3"></div>
      <div className="subscription-decoration--4"></div>
      <div className="subscription-decoration--5"></div>
      <div className="subscription-decoration--6"></div>
      <div className="subscription-decoration--7"></div>
      <div className="subscription-decoration--8"></div>
      <div className="subscription-decoration--9"></div>
    </div>
  );
};

export default SubscriptionDecorations;
